CREATE TRIGGER UNDGSubstanceRID_Version_Create
	ON UNDGSubstanceRID
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RID_PK, 'RID'
	FROM inserted
GO
CREATE TRIGGER UNDGSubstanceRID_Version_Update
	ON UNDGSubstanceRID
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RID_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
